def split(g):
    bl=[]
    for b in range(4):
        blk=[g[3*b+r][:] for r in range(3)]
        color=[v for row in blk for v in row if v][0]
        bl.append((color,blk))
    return bl

def cands(g,i,j):
    bl=split(g)
    out=[]
    for idx,(c,b) in enumerate(bl):
        if b[i][j]!=0:
            tot=sum(v!=0 for row in b for v in row)
            colc=sum(b[r][j]!=0 for r in range(3))
            rowc=sum(b[i][t]!=0 for t in range(6))
            out.append(dict(color=c,idx=idx,tot=tot,col=colc,row=rowc))
    return out

# consistency: for each demo, each output cell, output must equal selection per rule
def rule_predict(g, key, tiebreak):
    # key: function cand -> value; pick min value; ties by tiebreak value (min)
    out=[[0]*6 for _ in range(3)]
    for i in range(3):
        for j in range(6):
            cs=cands(g,i,j)
            if not cs: continue
            cs2=sorted(cs, key=lambda c:(key(c), tiebreak(c)))
            out[i][j]=cs2[0]['color']
    return out

